@abstractmethod
def __hash__(self):
    return 0

@classmethod
def __subclasshook__(cls, C):
    if cls is Hashable:
        return _check_methods(C, '__hash__')
    return NotImplemented

def _scan_name(self, i, declstartpos):
    rawdata = self.rawdata
    n = len(rawdata)
    if i == n:
        return (None, -1)
    m = _declname_match(rawdata, i)
    if m:
        s = m.group()
        name = s.strip()
        if i + len(s) == n:
            return (None, -1)
        return (name.lower(), m.end())
    else:
        self.updatepos(declstartpos, i)
        raise AssertionError('expected name token at %r' % rawdata[declstartpos:declstartpos + 20])

def _override_all_archs(_config_vars):
    """Allow override of all archs with ARCHFLAGS env var"""
    if 'ARCHFLAGS' in os.environ:
        arch = os.environ['ARCHFLAGS']
        for cv in _UNIVERSAL_CONFIG_VARS:
            if cv in _config_vars and '-arch' in _config_vars[cv]:
                flags = _config_vars[cv]
                flags = re.sub('-arch\\s+\\w+\\s', ' ', flags)
                flags = flags + ' ' + arch
                _save_modified_value(_config_vars, cv, flags)
    return _config_vars

def __subclasscheck__(cls, subclass):
    """Override for issubclass(subclass, cls)."""
    if not isinstance(subclass, type):
        raise TypeError('issubclass() arg 1 must be a class')
    if subclass in cls._abc_cache:
        return True
    if cls._abc_negative_cache_version < ABCMeta._abc_invalidation_counter:
        cls._abc_negative_cache = WeakSet()
        cls._abc_negative_cache_version = ABCMeta._abc_invalidation_counter
    elif subclass in cls._abc_negative_cache:
        return False
    ok = cls.__subclasshook__(subclass)
    if ok is not NotImplemented:
        assert isinstance(ok, bool)
        if ok:
            cls._abc_cache.add(subclass)
        else:
            cls._abc_negative_cache.add(subclass)
        return ok
    if cls in getattr(subclass, '__mro__', ()):
        cls._abc_cache.add(subclass)
        return True
    for rcls in cls._abc_registry:
        if issubclass(subclass, rcls):
            cls._abc_cache.add(subclass)
            return True
    for scls in cls.__subclasses__():
        if issubclass(subclass, scls):
            cls._abc_cache.add(subclass)
            return True
    cls._abc_negative_cache.add(subclass)
    return False

def __mod__(self, other):
    if isinstance(other, timedelta):
        r = self._to_microseconds() % other._to_microseconds()
        return timedelta(0, 0, r)
    return NotImplemented

def __divmod__(self, other):
    if isinstance(other, timedelta):
        q, r = divmod(self._to_microseconds(), other._to_microseconds())
        return (q, timedelta(0, 0, r))
    return NotImplemented

@property
def day(self):
    """day (1-31)"""
    return self._day

def __add__(self, other):
    """Add a date to a timedelta."""
    if isinstance(other, timedelta):
        o = self.toordinal() + other.days
        if 0 < o <= _MAXORDINAL:
            return type(self).fromordinal(o)
        raise OverflowError('result out of range')
    return NotImplemented

def date(self):
    """Return the date part."""
    return date(self._year, self._month, self._day)

@property
def real(self):
    return self

@property
def imag(self):
    return Decimal(0)

def fma(self, other, third, context=None):
    """Fused multiply-add.

    Returns self*other+third with no rounding of the intermediate
    product self*other.

    self and other are multiplied together, with no rounding of
    the result.  The third operand is then added to the result,
    and a single final rounding is performed."""
    other = _convert_other(other, raiseit=True)
    third = _convert_other(third, raiseit=True)
    if self._is_special or other._is_special:
        if context is None:
            context = getcontext()
        if self._exp == 'N':
            return context._raise_error(InvalidOperation, 'sNaN', self)
        if other._exp == 'N':
            return context._raise_error(InvalidOperation, 'sNaN', other)
        if self._exp == 'n':
            product = self
        elif other._exp == 'n':
            product = other
        elif self._exp == 'F':
            if not other:
                return context._raise_error(InvalidOperation, 'INF * 0 in fma')
            product = _SignedInfinity[self._sign ^ other._sign]
        elif other._exp == 'F':
            if not self:
                return context._raise_error(InvalidOperation, '0 * INF in fma')
            product = _SignedInfinity[self._sign ^ other._sign]
    else:
        product = _dec_from_triple(self._sign ^ other._sign, str(int(self._int) * int(other._int)), self._exp + other._exp)
    return product.__add__(third, context)

def rotate(self, other, context=None):
    """Returns a rotated copy of self, value-of-other times."""
    if context is None:
        context = getcontext()
    other = _convert_other(other, raiseit=True)
    ans = self._check_nans(other, context)
    if ans:
        return ans
    if other._exp != 0:
        return context._raise_error(InvalidOperation)
    if not -context.prec <= int(other) <= context.prec:
        return context._raise_error(InvalidOperation)
    if self._isinfinity():
        return Decimal(self)
    torot = int(other)
    rotdig = self._int
    topad = context.prec - len(rotdig)
    if topad > 0:
        rotdig = '0' * topad + rotdig
    elif topad < 0:
        rotdig = rotdig[-topad:]
    rotated = rotdig[torot:] + rotdig[:torot]
    return _dec_from_triple(self._sign, rotated.lstrip('0') or '0', self._exp)

def __deepcopy__(self, memo):
    if type(self) is Decimal:
        return self
    return self.__class__(str(self))

def is_canonical(self, a):
    """Return True if the operand is canonical; otherwise return False.

    Currently, the encoding of a Decimal instance is always
    canonical, so this method returns True for any Decimal.

    >>> ExtendedContext.is_canonical(Decimal('2.50'))
    True"""
    if not isinstance(a, Decimal):
        raise TypeError('is_canonical requires a Decimal as an argument.')
    return a.is_canonical()

def to_sci_string(self, a):
    """Converts a number to a string, using scientific notation.

    The operation is not affected by the context."""
    a = _convert_other(a, raiseit=True)
    return a.__str__(context=self)

def read1(self, size=-1):
    """Reads up to size bytes, with at most one read() system call."""
    self._checkClosed('read of closed file')
    if size < 0:
        size = self.buffer_size
    if size == 0:
        return b''
    with self._read_lock:
        self._peek_unlocked(1)
        return self._read_unlocked(min(size, len(self._read_buf) - self._read_pos))

def peek(self, size=0):
    self.flush()
    return BufferedReader.peek(self, size)

def _checkReadable(self):
    if not self._readable:
        raise UnsupportedOperation('File not open for reading')

def flush(self):
    self.buffer.flush()
    self._telling = self._seekable

def _get_decoded_chars(self, n=None):
    """Advance into the _decoded_chars buffer."""
    offset = self._decoded_chars_used
    if n is None:
        chars = self._decoded_chars[offset:]
    else:
        chars = self._decoded_chars[offset:offset + n]
    self._decoded_chars_used += len(chars)
    return chars

def _findall(haystack, needle):
    if not needle:
        return
    i = 0
    while True:
        i = haystack.find(needle, i)
        if i < 0:
            break
        yield i
        i += len(needle)

def __find_month_format(self, directive):
    """Find the month format appropriate for the current locale.

    In some locales (for example French and Hebrew), the default month
    used in __calc_date_time has the same name in full and abbreviated
    form.  Also, the month name can by accident match other part of the
    representation: the day of the week name (for example in Morisyen)
    or the month number (for example in Japanese).  Thus, cycle months
    of the year and find all positions that match the month name for
    each month,  If no common positions are found, the representation
    does not use the month name."""
    full_indices = abbr_indices = None
    for m in range(1, 13):
        time_tuple = time.struct_time((1999, m, 17, 22, 44, 55, 2, 76, 0))
        datetime = time.strftime(directive, time_tuple).lower()
        indices = set(_findall(datetime, self.f_month[m]))
        if full_indices is None:
            full_indices = indices
        else:
            full_indices &= indices
        indices = set(_findall(datetime, self.a_month[m]))
        if abbr_indices is None:
            abbr_indices = indices
        else:
            abbr_indices &= indices
        if not full_indices and (not abbr_indices):
            return (None, None)
    if full_indices:
        return (self.f_month, '%B')
    if abbr_indices:
        return (self.a_month, '%b')
    return (None, None)

def __setattr__(self, name, value):
    if name == '__dict__':
        raise AttributeError("%r object attribute '__dict__' is read-only" % self.__class__.__name__)
    with _patch(self):
        return object.__setattr__(self, name, value)

def local_deleted(_, key=key):
    thread = wrthread()
    if thread is not None:
        del thread.__dict__[key]

def __exit__(self, e, t, b):
    w = self.weakcontainer()
    if w is not None:
        s = w._iterating
        s.remove(self)
        if not s:
            w._commit_removals()

def _read_ushort(file):
    try:
        return struct.unpack('>H', file.read(2))[0]
    except struct.error:
        raise EOFError from None

def _readmark(self, chunk):
    nmarkers = _read_short(chunk)
    try:
        for i in range(nmarkers):
            id = _read_short(chunk)
            pos = _read_long(chunk)
            name = _read_string(chunk)
            if pos or name:
                self._markers.append((id, pos, name))
    except EOFError:
        w = 'Warning: MARK chunk contains only %s marker%s instead of %s' % (len(self._markers), '' if len(self._markers) == 1 else 's', nmarkers)
        warnings.warn(w)

def getframerate(self):
    if not self._framerate:
        raise Error('frame rate not set')
    return self._framerate

def _indent(self):
    self._current_indent += self._indent_increment
    self._level += 1

def _expand_help(self, action):
    params = dict(vars(action), prog=self._prog)
    for name in list(params):
        if params[name] is SUPPRESS:
            del params[name]
    for name in list(params):
        if hasattr(params[name], '__name__'):
            params[name] = params[name].__name__
    if params.get('choices') is not None:
        params['choices'] = ', '.join(map(str, params['choices']))
    return self._get_help_string(action) % params

def _parse_optional(self, arg_string):
    if not arg_string:
        return None
    if not arg_string[0] in self.prefix_chars:
        return None
    if arg_string in self._option_string_actions:
        action = self._option_string_actions[arg_string]
        return [(action, arg_string, None, None)]
    if len(arg_string) == 1:
        return None
    option_string, sep, explicit_arg = arg_string.partition('=')
    if sep and option_string in self._option_string_actions:
        action = self._option_string_actions[option_string]
        return [(action, option_string, sep, explicit_arg)]
    option_tuples = self._get_option_tuples(arg_string)
    if option_tuples:
        return option_tuples
    if self._negative_number_matcher.match(arg_string):
        if not self._has_negative_number_optionals:
            return None
    if ' ' in arg_string:
        return None
    return [(None, arg_string, None, None)]

def print_usage(self, file=None):
    if file is None:
        file = _sys.stdout
    self._print_message(self.format_usage(), file)

def exit(self, status=0, message=None):
    if message:
        self._print_message(message, _sys.stderr)
    _sys.exit(status)

def iter_fields(node):
    """Yield a tuple of ``(fieldname, value)`` for each field in ``node._fields``
    that is present on *node*."""
    for field in node._fields:
        try:
            yield (field, getattr(node, field))
        except AttributeError:
            pass

def generic_visit(self, node):
    """Called if no explicit visitor function exists for a node."""
    for field, value in iter_fields(node):
        if isinstance(value, list):
            for item in value:
                if isinstance(item, AST):
                    self.visit(item)
        elif isinstance(value, AST):
            self.visit(value)

def items_view(self, traverser, items):
    """Traverse and separate the given *items* with a comma and append it to
    the buffer. If *items* is a single item sequence, a trailing comma
    will be added."""
    if len(items) == 1:
        traverser(items[0])
        self.write(',')
    else:
        self.interleave(lambda: self.write(', '), traverser, items)

def __del__(self, _warn=warnings.warn):
    if not self.is_closed():
        _warn(f'unclosed event loop {self!r}', ResourceWarning, source=self)
        if not self.is_running():
            self.close()

def _timer_handle_cancelled(self, handle):
    """Notification that a TimerHandle has been cancelled."""
    if handle._scheduled:
        self._timer_cancelled_count += 1

async def _connect_pipes(self, waiter):
    try:
        proc = self._proc
        loop = self._loop
        if proc.stdin is not None:
            _, pipe = await loop.connect_write_pipe(lambda: WriteSubprocessPipeProto(self, 0), proc.stdin)
            self._pipes[0] = pipe
        if proc.stdout is not None:
            _, pipe = await loop.connect_read_pipe(lambda: ReadSubprocessPipeProto(self, 1), proc.stdout)
            self._pipes[1] = pipe
        if proc.stderr is not None:
            _, pipe = await loop.connect_read_pipe(lambda: ReadSubprocessPipeProto(self, 2), proc.stderr)
            self._pipes[2] = pipe
        assert self._pending_calls is not None
        loop.call_soon(self._protocol.connection_made, self)
        for callback, data in self._pending_calls:
            loop.call_soon(callback, *data)
        self._pending_calls = None
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        if waiter is not None and (not waiter.cancelled()):
            waiter.set_exception(exc)
    else:
        if waiter is not None and (not waiter.cancelled()):
            waiter.set_result(None)

def set_child_watcher(watcher):
    """Equivalent to calling
    get_event_loop_policy().set_child_watcher(watcher)."""
    return get_event_loop_policy().set_child_watcher(watcher)

def __init__(self, callback, args, loop, context=None):
    if context is None:
        context = contextvars.copy_context()
    self._context = context
    self._loop = loop
    self._callback = callback
    self._args = args
    self._cancelled = False
    self._repr = None
    if self._loop.get_debug():
        self._source_traceback = format_helpers.extract_stack(sys._getframe(1))
    else:
        self._source_traceback = None

def get_loop(self):
    """Return the event loop the Future is bound to."""
    loop = self._loop
    if loop is None:
        raise RuntimeError('Future object is not initialized.')
    return loop

def __init__(self):
    self._waiters = None
    self._locked = False

@property
def n_waiting(self):
    """Return the number of tasks currently waiting at the barrier."""
    if self._state is _BarrierState.FILLING:
        return self._count
    return 0

def _loop_writing(self, f=None, data=None):
    try:
        if f is not None and self._write_fut is None and self._closing:
            return
        assert f is self._write_fut
        self._write_fut = None
        self._pending_write = 0
        if f:
            f.result()
        if data is None:
            data = self._buffer
            self._buffer = None
        if not data:
            if self._closing:
                self._loop.call_soon(self._call_connection_lost, None)
            if self._eof_written:
                self._sock.shutdown(socket.SHUT_WR)
            self._maybe_resume_protocol()
        else:
            self._write_fut = self._loop._proactor.send(self._sock, data)
            if not self._write_fut.done():
                assert self._pending_write == 0
                self._pending_write = len(data)
                self._write_fut.add_done_callback(self._loop_writing)
                self._maybe_pause_protocol()
            else:
                self._write_fut.add_done_callback(self._loop_writing)
        if self._empty_waiter is not None and self._write_fut is None:
            self._empty_waiter.set_result(None)
    except ConnectionResetError as exc:
        self._force_close(exc)
    except OSError as exc:
        self._fatal_error(exc, 'Fatal write error on pipe transport')

def _format(self):
    result = f'maxsize={self._maxsize!r}'
    if getattr(self, '_queue', None):
        result += f' _queue={list(self._queue)!r}'
    if self._getters:
        result += f' _getters[{len(self._getters)}]'
    if self._putters:
        result += f' _putters[{len(self._putters)}]'
    if self._unfinished_tasks:
        result += f' tasks={self._unfinished_tasks}'
    return result

def _cancel_all_tasks(loop):
    to_cancel = tasks.all_tasks(loop)
    if not to_cancel:
        return
    for task in to_cancel:
        task.cancel()
    loop.run_until_complete(tasks.gather(*to_cancel, return_exceptions=True))
    for task in to_cancel:
        if task.cancelled():
            continue
        if task.exception() is not None:
            loop.call_exception_handler({'message': 'unhandled exception during asyncio.run() shutdown', 'exception': task.exception(), 'task': task})

def _force_close(self, exc):
    if self._conn_lost:
        return
    if self._buffer:
        self._buffer.clear()
        self._loop._remove_writer(self._sock_fd)
    if not self._closing:
        self._closing = True
        self._loop._remove_reader(self._sock_fd)
    self._conn_lost += 1
    self._loop.call_soon(self._call_connection_lost, exc)

def _write_send(self):
    assert self._buffer, 'Data should not be empty'
    if self._conn_lost:
        return
    try:
        buffer = self._buffer.popleft()
        n = self._sock.send(buffer)
        if n != len(buffer):
            self._buffer.appendleft(buffer[n:])
    except (BlockingIOError, InterruptedError):
        pass
    except (SystemExit, KeyboardInterrupt):
        raise
    except BaseException as exc:
        self._loop._remove_writer(self._sock_fd)
        self._buffer.clear()
        self._fatal_error(exc, 'Fatal write error on socket transport')
        if self._empty_waiter is not None:
            self._empty_waiter.set_exception(exc)
    else:
        self._maybe_resume_protocol()
        if not self._buffer:
            self._loop._remove_writer(self._sock_fd)
            if self._empty_waiter is not None:
                self._empty_waiter.set_result(None)
            if self._closing:
                self._call_connection_lost(None)
            elif self._eof:
                self._sock.shutdown(socket.SHUT_WR)

def _make_empty_waiter(self):
    if self._empty_waiter is not None:
        raise RuntimeError('Empty waiter is already set')
    self._empty_waiter = self._loop.create_future()
    if not self._buffer:
        self._empty_waiter.set_result(None)
    return self._empty_waiter

def get_read_buffer_size(self):
    """Return the current size of the read buffer."""
    return self._ssl_protocol._get_read_buffer_size()

def _do_write(self):
    try:
        while self._write_backlog:
            data = self._write_backlog[0]
            count = self._sslobj.write(data)
            data_len = len(data)
            if count < data_len:
                self._write_backlog[0] = data[count:]
                self._write_buffer_size -= count
            else:
                del self._write_backlog[0]
                self._write_buffer_size -= data_len
    except SSLAgainErrors:
        pass
    self._process_outgoing()

def _do_read(self):
    if self._state not in (SSLProtocolState.WRAPPED, SSLProtocolState.FLUSHING):
        return
    try:
        if not self._app_reading_paused:
            if self._app_protocol_is_buffer:
                self._do_read__buffered()
            else:
                self._do_read__copied()
            if self._write_backlog:
                self._do_write()
            else:
                self._process_outgoing()
        self._control_ssl_reading()
    except Exception as ex:
        self._fatal_error(ex, 'Fatal error on SSL protocol')

def _do_read__buffered(self):
    offset = 0
    count = 1
    buf = self._app_protocol_get_buffer(self._get_read_buffer_size())
    wants = len(buf)
    try:
        count = self._sslobj.read(wants, buf)
        if count > 0:
            offset = count
            while offset < wants:
                count = self._sslobj.read(wants - offset, buf[offset:])
                if count > 0:
                    offset += count
                else:
                    break
            else:
                self._loop.call_soon(lambda: self._do_read())
    except SSLAgainErrors:
        pass
    if offset > 0:
        self._app_protocol_buffer_updated(offset)
    if not count:
        self._call_eof_received()
        self._start_shutdown()

def _control_app_writing(self):
    size = self._get_write_buffer_size()
    if size >= self._outgoing_high_water and (not self._app_writing_paused):
        self._app_writing_paused = True
        try:
            self._app_protocol.pause_writing()
        except (KeyboardInterrupt, SystemExit):
            raise
        except BaseException as exc:
            self._loop.call_exception_handler({'message': 'protocol.pause_writing() failed', 'exception': exc, 'transport': self._app_transport, 'protocol': self})
    elif size <= self._outgoing_low_water and self._app_writing_paused:
        self._app_writing_paused = False
        try:
            self._app_protocol.resume_writing()
        except (KeyboardInterrupt, SystemExit):
            raise
        except BaseException as exc:
            self._loop.call_exception_handler({'message': 'protocol.resume_writing() failed', 'exception': exc, 'transport': self._app_transport, 'protocol': self})

def is_reading(self):
    """Return True if the transport is receiving."""
    raise NotImplementedError

def _process_self_data(self, data):
    for signum in data:
        if not signum:
            continue
        self._handle_signal(signum)

def __del__(self, _warn=warnings.warn):
    if self._pipe is not None:
        _warn(f'unclosed transport {self!r}', ResourceWarning, source=self)
        self._pipe.close()

def add_child_handler(self, pid, callback, *args):
    self._callbacks[pid] = (callback, args)
    self._do_waitpid(pid)

def _unregister_wait(self):
    if not self._registered:
        return
    self._registered = False
    wait_handle = self._wait_handle
    self._wait_handle = None
    try:
        _overlapped.UnregisterWait(wait_handle)
    except OSError as exc:
        if exc.winerror != _overlapped.ERROR_IO_PENDING:
            context = {'message': 'Failed to unregister the wait handle', 'exception': exc, 'future': self}
            if self._source_traceback:
                context['source_traceback'] = self._source_traceback
            self._loop.call_exception_handler(context)
            return
    self._unregister_wait_cb(None)

def _poll(self, timeout=None):
    if timeout is None:
        ms = INFINITE
    elif timeout < 0:
        raise ValueError('negative timeout')
    else:
        ms = math.ceil(timeout * 1000.0)
        if ms >= INFINITE:
            raise ValueError('timeout too big')
    while True:
        status = _overlapped.GetQueuedCompletionStatus(self._iocp, ms)
        if status is None:
            break
        ms = 0
        err, transferred, key, address = status
        try:
            f, ov, obj, callback = self._cache.pop(address)
        except KeyError:
            if self._loop.get_debug():
                self._loop.call_exception_handler({'message': 'GetQueuedCompletionStatus() returned an unexpected event', 'status': 'err=%s transferred=%s key=%#x address=%#x' % (err, transferred, key, address)})
            if key not in (0, _overlapped.INVALID_HANDLE_VALUE):
                _winapi.CloseHandle(key)
            continue
        if obj in self._stopped_serving:
            f.cancel()
        elif not f.done():
            try:
                value = callback(transferred, key, ov)
            except OSError as e:
                f.set_exception(e)
                self._results.append(f)
            else:
                f.set_result(value)
                self._results.append(f)
            finally:
                f = None
    for ov in self._unregistered:
        self._cache.pop(ov.address, None)
    self._unregistered.clear()

def b64encode(s, altchars=None):
    """Encode the bytes-like object s using Base64 and return a bytes object.

    Optional altchars should be a byte string of length 2 which specifies an
    alternative alphabet for the '+' and '/' characters.  This allows an
    application to e.g. generate url or filesystem safe Base64 strings."""
    encoded = binascii.b2a_base64(s, newline=False)
    if altchars is not None:
        assert len(altchars) == 2, repr(altchars)
        return encoded.translate(bytes.maketrans(b'+/', altchars))
