def _send_bytes(self, buf):
    n = len(buf)
    if n > 2147483647:
        pre_header = struct.pack('!i', -1)
        header = struct.pack('!Q', n)
        self._send(pre_header)
        self._send(header)
        self._send(buf)
    else:
        header = struct.pack('!i', n)
        if n > 16384:
            self._send(header)
            self._send(buf)
        else:
            self._send(header + buf)

