    if self._level == 0:
        self._builder._parser.StartElementHandler = self._old_start
        self._builder._parser.EndElementHandler = self._old_end
        self._builder = None
    else:
        self._level = self._level - 1
        self._old_end(*args)

def __init__(self, context, options=None):
    if context.nodeType == DOCUMENT_NODE:
        self.originalDocument = context
        self.context = context
    else:
        self.originalDocument = context.ownerDocument
        self.context = context
    ExpatBuilder.__init__(self, options)

def parseString(self, string):
    try:
        ExpatBuilder.parseString(self, string)
    except ParseEscape:
        pass

def item(self, index):
    if 0 <= index < len(self):
        return self[index]

def _get_elements_by_tagName_ns_helper(parent, nsURI, localName, rc):
    for node in parent.childNodes:
        if node.nodeType == Node.ELEMENT_NODE:
            if (localName == '*' or node.localName == localName) and (nsURI == '*' or node.namespaceURI == nsURI):
                rc.append(node)
            _get_elements_by_tagName_ns_helper(node, nsURI, localName, rc)
    return rc

def parse(file, parser=None, bufsize=None):
    """Parse a file into a DOM by filename or file object."""
    if parser is None and (not bufsize):
        from xml.dom import expatbuilder
        return expatbuilder.parse(file)
    else:
        from xml.dom import pulldom
        return _do_pulldom_parse(pulldom.parse, (file,), {'parser': parser, 'bufsize': bufsize})

def unlink(self):
    elem = self.ownerElement
    if elem is not None:
        del elem._attrs[self.nodeName]
        del elem._attrsNS[self.namespaceURI, self.localName]
        if self._is_id:
            self._is_id = False
            elem._magic_id_nodes -= 1
            self.ownerDocument._magic_id_count -= 1
    for child in self.childNodes:
        child.unlink()
    del self.childNodes[:]

def _get_wholeText(self):
    L = [self.data]
    n = self.previousSibling
    while n is not None:
        if n.nodeType in (Node.TEXT_NODE, Node.CDATA_SECTION_NODE):
            L.insert(0, n.data)
            n = n.previousSibling
        else:
            break
    n = self.nextSibling
    while n is not None:
        if n.nodeType in (Node.TEXT_NODE, Node.CDATA_SECTION_NODE):
            L.append(n.data)
            n = n.nextSibling
        else:
            break
    return ''.join(L)

def _get_isWhitespaceInElementContent(self):
    if self.data.strip():
        return False
    elem = _get_containing_element(self)
    if elem is None:
        return False
    info = self.ownerDocument._get_elem_info(elem)
    if info is None:
        return False
    else:
        return info.isElementContent()

def __getitem__(self, name_or_tuple):
    if isinstance(name_or_tuple, tuple):
        node = self.getNamedItemNS(*name_or_tuple)
    else:
        node = self.getNamedItem(name_or_tuple)
    if node is None:
        raise KeyError(name_or_tuple)
    return node

def endElementNS(self, name, tagName):
    self.lastEvent[1] = [(END_ELEMENT, self.pop()), None]
    self.lastEvent = self.lastEvent[1]

def setFeature(self, name, state):
    if self.supportsFeature(name):
        state = state and 1 or 0
        try:
            settings = self._settings[_name_xform(name), state]
        except KeyError:
            raise xml.dom.NotSupportedErr('unsupported feature: %r' % (name,)) from None
        else:
            for name, value in settings:
                setattr(self._options, name, value)
    else:
        raise xml.dom.NotFoundErr('unknown feature: ' + repr(name))

def saveXML(self, snode):
    if snode is None:
        snode = self
    elif snode.ownerDocument is not self:
        raise xml.dom.WrongDocumentErr()
    return snode.toxml()

def select(context, result):
    parent_map = get_parent_map(context)
    result_map = {}
    for elem in result:
        if elem in parent_map:
            parent = parent_map[elem]
            if parent not in result_map:
                result_map[parent] = None
                yield parent

def select_negated(context, result):
    for elem in result:
        for e in elem.iterfind(tag):
            if ''.join(e.itertext()) != value:
                yield elem
                break

def findall(self, path, namespaces=None):
    """Find all matching subelements by tag name or path.

    *path* is a string having either an element tag or an XPath,
    *namespaces* is an optional mapping from namespace prefix to full name.

    Returns list containing all matching elements in document order."""
    return ElementPath.findall(self, path, namespaces)

def __str__(self):
    """Create a string representation of the exception."""
    return self._msg

def prepareParser(self, source):
    if source.getSystemId() is not None:
        self._parser.SetBase(source.getSystemId())

def prepare_input_source(source, base=''):
    """This function takes an InputSource and an optional base URL and
    returns a fully resolved InputSource object ready for reading."""
    if isinstance(source, os.PathLike):
        source = os.fspath(source)
    if isinstance(source, str):
        source = xmlreader.InputSource(source)
    elif hasattr(source, 'read'):
        f = source
        source = xmlreader.InputSource()
        if isinstance(f.read(0), str):
            source.setCharacterStream(f)
        else:
            source.setByteStream(f)
        if hasattr(f, 'name') and isinstance(f.name, str):
            source.setSystemId(f.name)
    if source.getCharacterStream() is None and source.getByteStream() is None:
        sysid = source.getSystemId()
        basehead = os.path.dirname(os.path.normpath(base))
        sysidfilename = os.path.join(basehead, sysid)
        if os.path.isfile(sysidfilename):
            source.setSystemId(sysidfilename)
            f = open(sysidfilename, 'rb')
        else:
            source.setSystemId(urllib.parse.urljoin(base, sysid))
            f = urllib.request.urlopen(source.getSystemId())
        source.setByteStream(f)
    return source

def setFeature(self, name, state):
    """Sets the state of a SAX2 feature."""
    raise SAXNotRecognizedException("Feature '%s' not recognized" % name)

def make_comparable(self, other):
    if isinstance(other, DateTime):
        s = self.value
        o = other.value
    elif isinstance(other, datetime):
        s = self.value
        o = _iso8601_format(other)
    elif isinstance(other, str):
        s = self.value
        o = other
    elif hasattr(other, 'timetuple'):
        s = self.timetuple()
        o = other.timetuple()
    else:
        s = self
        o = NotImplemented
    return (s, o)

def __lt__(self, other):
    s, o = self.make_comparable(other)
    if o is NotImplemented:
        return NotImplemented
    return s < o

def close(self):
    try:
        parser = self._parser
    except AttributeError:
        pass
    else:
        del self._target, self._parser
        parser.Parse(b'', True)

def close(self):
    if self._type is None or self._marks:
        raise ResponseError()
    if self._type == 'fault':
        raise Fault(**self._stack[0])
    return tuple(self._stack)

def end_nil(self, data):
    self.append(None)
    self._value = 0

def markup(self, text, escape=None, funcs={}, classes={}, methods={}):
    """Mark up some plain text, given a context of symbols to look for.
    Each context dictionary maps object names to anchor names."""
    escape = escape or self.escape
    results = []
    here = 0
    pattern = re.compile('\\b((http|https|ftp)://\\S+[\\w/]|RFC[- ]?(\\d+)|PEP[- ]?(\\d+)|(self\\.)?((?:\\w|\\.)+))\\b')
    while (match := pattern.search(text, here)):
        start, end = match.span()
        results.append(escape(text[here:start]))
        all, scheme, rfc, pep, selfdot, name = match.groups()
        if scheme:
            url = escape(all).replace('"', '&quot;')
            results.append('<a href="%s">%s</a>' % (url, url))
        elif rfc:
            url = 'https://www.rfc-editor.org/rfc/rfc%d.txt' % int(rfc)
            results.append('<a href="%s">%s</a>' % (url, escape(all)))
        elif pep:
            url = 'https://peps.python.org/pep-%04d/' % int(pep)
            results.append('<a href="%s">%s</a>' % (url, escape(all)))
        elif text[end:end + 1] == '(':
            results.append(self.namelink(name, methods, funcs, classes))
        elif selfdot:
            results.append('self.<strong>%s</strong>' % name)
        else:
            results.append(self.namelink(name, classes))
        here = end
    results.append(escape(text[here:]))
    return ''.join(results)

def _sanitize_filename(filename):
    """Terminate the file name at the first null byte and
    ensure paths always use forward slashes as the directory separator."""
    null_byte = filename.find(chr(0))
    if null_byte >= 0:
        filename = filename[0:null_byte]
    if os.sep != '/' and os.sep in filename:
        filename = filename.replace(os.sep, '/')
    if os.altsep and os.altsep != '/' and (os.altsep in filename):
        filename = filename.replace(os.altsep, '/')
    return filename

def namelist(self):
    names = super().namelist()
    return names + list(self._implied_dirs(names))

def _validate_tzfile_path(path, _base=_TEST_PATH):
    if os.path.isabs(path):
        raise ValueError(f'ZoneInfo keys may not be absolute paths, got: {path}')
    new_path = os.path.normpath(path)
    if len(new_path) != len(path):
        raise ValueError(f'ZoneInfo keys must be normalized relative paths, got: {path}')
    resolved = os.path.normpath(os.path.join(_base, new_path))
    if not resolved.startswith(_base):
        raise ValueError(f'ZoneInfo keys must refer to subdirectories of TZPATH, got: {path}')

def __new__(cls, key):
    instance = cls._weak_cache.get(key, None)
    if instance is None:
        instance = cls._weak_cache.setdefault(key, cls._new_instance(key))
        instance._from_cache = True
    cls._strong_cache[key] = cls._strong_cache.pop(key, instance)
    if len(cls._strong_cache) > cls._strong_cache_size:
        cls._strong_cache.popitem(last=False)
    return instance

@classmethod
def no_cache(cls, key):
    obj = cls._new_instance(key)
    obj._from_cache = False
    return obj

@classmethod
def clear_cache(cls, *, only_keys=None):
    if only_keys is not None:
        for key in only_keys:
            cls._weak_cache.pop(key, None)
            cls._strong_cache.pop(key, None)
    else:
        cls._weak_cache.clear()
        cls._strong_cache.clear()

@classmethod
def _ymd2ord(cls, year, month, day):
    return _post_epoch_days_before_year(year) + cls._DAYS_BEFORE_MONTH[month] + (month > 2 and calendar.isleap(year)) + day
